from typing import List

class Solution:
    def maxProfitAssignment(self, difficulty: List[int], profit: List[int], worker: List[int]) -> int:
        jobs = sorted(zip(difficulty, profit))
        worker.sort()
        ans = 0
        max_profit = 0
        i = 0
        n = len(jobs)

        for ability in worker:
            while i < n and jobs[i][0] <= ability:
                if jobs[i][1] > max_profit:
                    max_profit = jobs[i][1]
                i += 1
            ans += max_profit

        return ans

class Solution {
public:
    int maxProfitAssignment(vector<int>& difficulty, vector<int>& profit, vector<int>& worker) {
        int n = difficulty.size();
        vector<pair<int, int>> jobs(n);
        for (int i = 0; i < n; i++) jobs[i] = {difficulty[i], profit[i]};
        sort(jobs.begin(), jobs.end());
        sort(worker.begin(), worker.end());
        int ans = 0, max_profit = 0, i = 0;
        for (int ability : worker) {
            while (i < n && jobs[i].first <= ability) {
                max_profit = max(max_profit, jobs[i].second);
                i++;
            }
            ans += max_profit;
        }
        return ans;
    }
};

class Solution {
    public int maxProfitAssignment(int[] difficulty, int[] profit, int[] worker) {
        int n = difficulty.length;
        int[][] jobs = new int[n][2];
        for (int i = 0; i < n; i++) {
            jobs[i][0] = difficulty[i];
            jobs[i][1] = profit[i];
        }
        Arrays.sort(jobs, (a, b) -> Integer.compare(a[0], b[0]));
        Arrays.sort(worker);
        int ans = 0, maxProfit = 0, i = 0;
        for (int ability : worker) {
            while (i < n && jobs[i][0] <= ability) {
                maxProfit = Math.max(maxProfit, jobs[i][1]);
                i++;
            }
            ans += maxProfit;
        }
        return ans;
    }
}

var maxProfitAssignment = function(difficulty, profit, worker) {
    const n = difficulty.length;
    const jobs = Array.from({ length: n }, (_, i) => [difficulty[i], profit[i]]);
    jobs.sort((a, b) => a[0] - b[0]);
    worker.sort((a, b) => a - b);
    let ans = 0, maxProfit = 0, i = 0;
    for (const ability of worker) {
        while (i < n && jobs[i][0] <= ability) {
            if (jobs[i][1] > maxProfit) maxProfit = jobs[i][1];
            i++;
        }
        ans += maxProfit;
    }
    return ans;
};
